<?php declare( strict_types=1 ); namespace Inc\Controllers\Exam; use Inc\Contracts\ServiceInterface; use Inc\Enums\Wp\ShortCode; use Inc\Core\BaseController; class ExamGuestPageController extends BaseController implements ServiceInterface { public function register(): void { add_shortcode( ShortCode::ExamGuestEntry->value, [ $this, 'renderGuestEntryForm' ] ); add_filter( 'template_include', [ $this, 'filterTemplateForGuestPage' ], 99 ); } public function renderGuestEntryForm( array $atts ): string { if ( is_user_logged_in() ) { return '<p>Авторизованные пользователи используют личный кабинет.</p>'; } ob_start(); ?> <div class="fs-lms-exam-guest-entry"> <form id="exam-guest-form" method="post"> <div class="exam-guest-field"> <label for="guest-name">ФИО:</label> <input type="text" id="guest-name" name="guest_name" required /> </div> <div class="exam-guest-field"> <label for="guest-phone">Телефон:</label> <input type="tel" id="guest-phone" name="guest_phone" required /> </div> <div class="exam-guest-field"> <label for="guest-email">Email:</label> <input type="email" id="guest-email" name="guest_email" required /> </div> <button type="submit" class="button button-primary">Далее</button> </form> </div> <?php return ob_get_clean(); } public function filterTemplateForGuestPage( string $template ): string { if ( is_page() ) { $page = get_queried_object(); if ( $page && has_shortcode( $page->post_content, ShortCode::ExamGuestEntry->value ) ) { return $this->path( 'templates/clean-page.php' ); } } return $template; } }
